import type { CodeGenerator } from "skir-internal";

import { BLANK, indent, lowerCamel, quoted, separated, upperCamel, type Lines } from "../../text.js";
import type { ResolvedFailure, ResolvedOperation, ResolvedOperations, ResolvedParameter } from "../resolve.js";
import { concreteItem, type Signature } from "../signature.js";
import { emitDartUnicodeTables, type UnicodeTables } from "../unicode.js";
import {
  boundOf,
  frameworkRecord,
  namedKind,
  operationGroups,
  renderDeclarations,
  unwrapped,
  valueVariable,
  wrapWords,
} from "./shared.js";

const HEADER = [
  "// Generated by skir gen (typewriter operations, Dart target) from operations.yaml. Do not edit.",
  "// ignore_for_file: avoid_classes_with_only_static_members, lines_longer_than_80_chars, no_leading_underscores_for_library_prefixes, unnecessary_lambdas",
];

/** Dart reserved words that cannot name a kernel group, method or parameter. */
const DART_RESERVED = new Set(["assert", "break", "case", "catch", "class", "const", "continue", "default", "do", "else", "enum", "extends", "false", "final", "finally", "for", "if", "in", "is", "new", "null", "rethrow", "return", "super", "switch", "this", "throw", "true", "try", "var", "void", "while", "with"]);

/** Collects the import directives of the referenced Skir declarations. */
class Imports {
  private readonly directives = new Set<string>();

  constructor(private readonly symbols: CodeGenerator.SymbolProvider) {}

  add(directive: string): void {
    this.directives.add(directive);
  }

  /** The Dart reference to a Skir record after recording its imports. */
  record(location: Parameters<CodeGenerator.SymbolProvider["record"]>[0]): string {
    const symbol = this.symbols.record(location);
    symbol.imports.forEach((directive) => this.directives.add(directive));
    return symbol.reference;
  }

  lines(): Lines {
    return [...this.directives].sort();
  }
}

interface Skir {
  readonly dataValue: string;
  readonly listItem: string;
  readonly mapRow: string;
  readonly linkValue: string;
  readonly resourceId: string;
  readonly typeUse: string;
  readonly failureId: string;
  readonly namedValue: string;
  readonly namedTypeUse: string;
  readonly typeDefinitionId: string;
  readonly typeId: string;
  readonly declaredTypeId: string;
  readonly imports: Imports;
}

/**
 * Emits the Dart operation catalog into the panel's Skir library: kernel interfaces for every operation (panel
 * profile included), the kernel holder, the dispatch the evaluator's call rule uses, declarations, failure ids and the
 * manifest's enums and records. Skir names come from the Dart symbol provider.
 */
export function emitDartOperations(
  catalog: ResolvedOperations,
  unicode: UnicodeTables,
  symbols: CodeGenerator.SymbolProvider,
  input: Pick<CodeGenerator.Input<unknown>, "modules">,
  runtimeImport: string,
): CodeGenerator.OutputFile[] {
  const imports = new Imports(symbols);
  imports.add(`import "${runtimeImport}";`);
  const record = (reference: string) => imports.record(frameworkRecord(input, reference));
  const skir: Skir = {
    dataValue: record("editor/v1/type_catalog.skir:DataValue"),
    listItem: record("editor/v1/type_catalog.skir:ListItem"),
    mapRow: record("editor/v1/type_catalog.skir:MapRow"),
    linkValue: record("editor/v1/type_catalog.skir:LinkValue"),
    resourceId: record("editor/v1/type_catalog.skir:ResourceId"),
    typeUse: record("editor/v1/type_catalog.skir:TypeUse"),
    failureId: record("editor/v1/expression.skir:FailureId"),
    namedValue: record("editor/v1/type_catalog.skir:NamedValue"),
    namedTypeUse: record("editor/v1/type_catalog.skir:NamedTypeUse"),
    typeDefinitionId: record("editor/v1/type_catalog.skir:TypeDefinitionId"),
    typeId: record("editor/v1/type_catalog.skir:TypeId"),
    declaredTypeId: record("editor/v1/type_catalog.skir:DeclaredTypeId"),
    imports,
  };
  const body = separated([
    ...typeDeclarations(catalog, skir),
    failures(catalog, skir),
    declarations(catalog),
    ...kernels(catalog, skir),
    invoker(catalog, skir),
  ]);
  return [
    {
      path: "portable_operations.dart",
      code: renderDeclarations([...HEADER, BLANK, ...imports.lines(), BLANK, ...body]),
    },
    { path: "portable_unicode_tables.dart", code: emitDartUnicodeTables(unicode) },
  ];
}

function doc(text: string): Lines {
  return wrapWords(text, 76).map((line) => `/// ${line}`);
}

function safe(name: string): string {
  return DART_RESERVED.has(name) ? `${name}Value` : name;
}

function groupField(group: string): string {
  return group === "enum" ? "enumeration" : safe(lowerCamel(group));
}

// Enums and records

function typeUse(skir: Skir, typeId: string): string {
  return `${skir.namedTypeUse}(definition: ${skir.typeDefinitionId}(typeId: ${skir.typeId}.wrapDeclared(${skir.declaredTypeId}(value: ${quoted(typeId)})), revision: 1), arguments: const [])`;
}

function typeDeclarations(catalog: ResolvedOperations, skir: Skir): Lines[] {
  const enums = catalog.enums.map((enumeration): Lines => {
    const name = upperCamel(enumeration.name);
    return [
      ...doc(enumeration.doc),
      `enum ${name} {`,
      ...indent(
        [
          ...enumeration.cases.map(
            (value, index) => `${safe(lowerCamel(value))}(${quoted(upperCamel(value))})${index === enumeration.cases.length - 1 ? ";" : ","}`,
          ),
          BLANK,
          `const ${name}(this.caseName);`,
          BLANK,
          "/// The catalog case name, as Kotlin declares it.",
          "final String caseName;",
          BLANK,
          "/// The catalog type of this enumeration.",
          `static ${skir.namedTypeUse} get type => ${typeUse(skir, enumeration.typeId)};`,
          BLANK,
          `${skir.dataValue} toDataValue() => ${skir.dataValue}.wrapNamed(${skir.namedValue}(actualType: type, payload: ${skir.dataValue}.wrapEnumCase(caseName)));`,
          BLANK,
          `static ${name} fromDataValue(${skir.dataValue} value) {`,
          ...indent([
            "final caseName = value.asEnumCase();",
            `for (final candidate in ${name}.values) {`,
            ...indent(["if (candidate.caseName == caseName) return candidate;"]),
            "}",
            `throw PortableOperationFailure(PortableFailures.illTypedArgument, "Expected a ${name} case.");`,
          ]),
          "}",
        ],
        1,
      ),
      "}",
    ];
  });
  const records = catalog.records.map((record): Lines => {
    const name = upperCamel(record.name);
    const fields = record.fields.map((field) => ({ ...field, key: lowerCamel(field.name) }));
    return [
      ...doc(record.doc),
      `final class ${name} {`,
      ...indent(
        [
          `const ${name}({${fields.map((field) => `required this.${field.key}`).join(", ")}});`,
          BLANK,
          ...fields.map((field) => `final ${recordFieldType(field.type)} ${field.key};`),
          BLANK,
          "/// The catalog type of this record.",
          `static ${skir.namedTypeUse} get type => ${typeUse(skir, record.typeId)};`,
          BLANK,
          `${skir.dataValue} toDataValue() => ${skir.dataValue}.wrapNamed(`,
          ...indent([
            `${skir.namedValue}(`,
            ...indent([
              "actualType: type,",
              `payload: recordValue({`,
              ...indent(fields.map((field) => `${quoted(field.key)}: ${encode(field.type, field.key, catalog)},`)),
              "}),",
            ]),
            "),",
          ]),
          ");",
          BLANK,
          `static ${name} fromDataValue(${skir.dataValue} value) {`,
          ...indent([
            "final fields = value.asRecordFields();",
            `${skir.dataValue} field(String name) =>`,
            ...indent([`fields[name] ?? (throw PortableOperationFailure(PortableFailures.illTypedArgument, "Expected a ${name}."));`]),
            `return ${name}(`,
            ...indent(fields.map((field) => `${field.key}: ${decode(field.type, `field(${quoted(field.key)})`, catalog)},`)),
            ");",
          ]),
          "}",
        ],
        1,
      ),
      "}",
    ];
  });
  return [...enums, ...records];
}

function recordFieldType(type: Signature): string {
  switch (type.kind) {
    case "scalar":
      return KERNEL_SCALARS[type.scalar]!;
    case "named":
      return upperCamel(type.name);
    case "nullable":
      return `${recordFieldType(type.value)}?`;
    case "list":
      return `List<${recordFieldType(type.value)}>`;
    default:
      throw new Error(`unsupported record field type ${type.kind}`);
  }
}

// Failures and declarations

function failures(catalog: ResolvedOperations, skir: Skir): Lines {
  const all: ResolvedFailure[] = [...catalog.failures, ...catalog.evaluatorFailures];
  return [
    "/// Every failure kernels and the evaluator raise, declared in operations.yaml.",
    "abstract final class PortableFailures {",
    ...indent(
      separated([
        ...all.map((failure): Lines => [
          ...doc(failure.message),
          `static final ${lowerCamel(failure.id)} = ${skir.failureId}(value: ${quoted(failure.id)});`,
        ]),
        [
          "/// The declared message of every failure, by id.",
          "static const messages = <String, String>{",
          ...indent(all.map((failure) => `${quoted(failure.id)}: ${quoted(failure.message, "escaped")},`)),
          "};",
        ],
        [
          "/// The failures each operation declares, by operation id.",
          "static const declared = <String, List<String>>{",
          ...indent(
            catalog.operations
              .filter((operation) => operation.failures.length > 0)
              .map((operation) => `${quoted(operation.id)}: [${operation.failures.map((failure) => quoted(failure)).join(", ")}],`),
          ),
          "};",
        ],
      ]),
    ),
    "}",
  ];
}

const PARAMETER_KINDS: Record<ResolvedParameter["kind"], string> = {
  value: "PortableParameterKind.value",
  partial: "PortableParameterKind.partial",
  located: "PortableParameterKind.located",
  each: "PortableParameterKind.each",
  step: "PortableParameterKind.step",
  comparator: "PortableParameterKind.comparator",
  apply: "PortableParameterKind.apply",
};

function declarations(catalog: ResolvedOperations): Lines {
  return [
    "/// The declaration of operation [id], or null when this build does not know it.",
    "PortableOperationDeclaration? portableOperation(String id) => switch (id) {",
    ...indent(
      catalog.operations.map(
        (operation) =>
          `${quoted(operation.id)} => const PortableOperationDeclaration(id: ${quoted(operation.id)}, profile: PortableProfile.${operation.profile}, parameters: [${operation.parameters
            .map((parameter) => PARAMETER_KINDS[parameter.kind])
            .join(", ")}], variadic: ${operation.parameters.at(-1)?.variadic ?? false}, typeArguments: ${operation.typeParameters.filter((parameter) => parameter.explicit).length}),`,
      ),
    ),
    ...indent(["_ => null,"]),
    "};",
    BLANK,
    "/// Every declared operation id, in id order.",
    "const portableOperationIds = <String>[",
    ...indent(catalog.operations.map((operation) => `${quoted(operation.id)},`)),
    "];",
  ];
}

// Kernel types and conversions

const KERNEL_SCALARS: Record<string, string> = {
  text: "String",
  boolean: "bool",
  int32: "int",
  integer: "BigInt",
  float: "double",
  decimal: "PortableDecimal",
  bytes: "ByteString",
  duration: "Duration",
  timestamp: "DateTime",
};

function kernelType(type: Signature, operation: ResolvedOperation, catalog: ResolvedOperations, skir: Skir): string {
  const nested = (value: Signature) => kernelType(value, operation, catalog, skir);
  switch (type.kind) {
    case "scalar":
      return type.scalar === "resource_id" ? skir.resourceId : KERNEL_SCALARS[type.scalar]!;
    case "named": {
      const named = namedKind(catalog, type.name);
      return named.kind === "read_model" ? skir.dataValue : upperCamel(type.name);
    }
    case "variable": {
      const bound = boundOf(operation, type.name);
      return bound === "numeric" ? "PortableNumber" : bound === "integer" ? "BigInt" : skir.dataValue;
    }
    case "nullable":
      return type.value.kind === "variable" && valueVariable(operation, type.value.name) ? skir.dataValue : `${nested(type.value)}?`;
    case "list":
    case "set":
    case "items":
      return concreteItem(type.value) ? `List<${nested(type.value)}>` : `List<${skir.listItem}>`;
    case "map":
      return `List<${skir.mapRow}>`;
    case "entry":
    case "field_type":
    case "representation":
      return skir.dataValue;
    case "link":
      return skir.linkValue;
    case "partial":
      return nested(type.value);
    case "located":
      return `Located<${nested(type.value)}>`;
    case "maybe":
      return `PortableMaybe<${nested(type.value)}>`;
    case "each":
      return `List<${nested(type.output)}>`;
    case "step":
      return "PortableStep";
    case "comparator":
      return "PortableComparator";
    case "apply":
      return "PortableApply";
    case "field_of":
      return "String";
  }
}

function decode(type: Signature, value: string, catalog: ResolvedOperations, operation?: ResolvedOperation): string {
  const nested = (inner: Signature, expression: string) => decode(inner, expression, catalog, operation);
  switch (type.kind) {
    case "scalar":
      return `${value}.as${upperCamel(type.scalar)}()`;
    case "named": {
      const named = namedKind(catalog, type.name);
      return named.kind === "read_model" ? value : `${upperCamel(type.name)}.fromDataValue(${value})`;
    }
    case "variable": {
      const bound = operation ? boundOf(operation, type.name) : "any";
      return bound === "numeric" ? `${value}.asNumber()` : bound === "integer" ? `${value}.asInteger()` : value;
    }
    case "nullable":
      return type.value.kind === "variable" && valueVariable(operation, type.value.name)
        ? value
        : `${value}.asNullable((it) => ${nested(type.value, "it")})`;
    case "list":
    case "set":
    case "items":
      return concreteItem(type.value) ? `[for (final it in ${value}.asItems()) ${nested(type.value, "it.value")}]` : `${value}.asItems()`;
    case "map":
      return `${value}.asRows()`;
    case "link":
      return `${value}.asLink()`;
    case "field_of":
      return `${value}.asText()`;
    case "entry":
    case "field_type":
    case "representation":
      return value;
    case "partial":
    case "located":
      return nested(type.value, value);
    default:
      throw new Error(`${type.kind} is not decoded from a value`);
  }
}

function encode(type: Signature, value: string, catalog: ResolvedOperations, operation?: ResolvedOperation): string {
  const nested = (inner: Signature, expression: string) => encode(inner, expression, catalog, operation);
  switch (type.kind) {
    case "scalar":
      return `${lowerCamel(type.scalar)}Value(${value})`;
    case "named": {
      const named = namedKind(catalog, type.name);
      return named.kind === "read_model" ? value : `${value}.toDataValue()`;
    }
    case "variable": {
      const bound = operation ? boundOf(operation, type.name) : "any";
      return bound === "numeric" ? `numberValue(${value})` : bound === "integer" ? `integerValue(${value})` : value;
    }
    case "nullable":
      return type.value.kind === "variable" && valueVariable(operation, type.value.name)
        ? value
        : `nullableValue(${value}, (it) => ${nested(type.value, "it")})`;
    case "list":
      return concreteItem(type.value) ? `positionalList([for (final it in ${value}) ${nested(type.value, "it")}])` : `itemsList(${value})`;
    case "set":
      return concreteItem(type.value)
        ? `itemsSet(positionalItems([for (final it in ${value}) ${nested(type.value, "it")}]))`
        : `itemsSet(${value})`;
    case "map":
      return `rowsMap(${value})`;
    case "link":
      return `linkValue(${value})`;
    case "entry":
    case "field_type":
    case "representation":
      return value;
    default:
      throw new Error(`${type.kind} is not an encodable result`);
  }
}

// Kernels

function kernelName(group: string): string {
  return `${upperCamel(group)}Kernel`;
}

function methodName(operation: ResolvedOperation): string {
  return safe(lowerCamel(operation.name));
}

function kernelParameters(operation: ResolvedOperation, catalog: ResolvedOperations, skir: Skir): string[] {
  const values = operation.parameters.map((parameter) => {
    const type = kernelType(parameter.type, operation, catalog, skir);
    return `${parameter.variadic ? `List<${type}>` : type} ${safe(lowerCamel(parameter.name))}`;
  });
  const types = operation.typeParameters
    .filter((parameter) => parameter.explicit)
    .map((parameter) => `${skir.typeUse} ${parameter.name.toLowerCase()}Type`);
  const capabilities = operation.uses.map((use) =>
    use === "meter" ? "PortableMeter meter" : use === "types" ? "PortableTypes types" : "PortableResources resources",
  );
  return [...values, ...types, ...capabilities];
}

function kernels(catalog: ResolvedOperations, skir: Skir): Lines[] {
  const groups = operationGroups(catalog.operations);
  const interfaces = groups.map(([group, operations]): Lines => [
    `/// The operations of group ${group}. A kernel that misses a method does not analyze.`,
    `abstract interface class ${kernelName(group)} {`,
    ...indent(
      separated(
        operations.map((operation): Lines => {
          const parameters = kernelParameters(operation, catalog, skir);
          const head = `${kernelType(operation.result, operation, catalog, skir)} ${methodName(operation)}(`;
          return [
            ...doc(`${operation.doc}${operation.profile === "panel" ? " Panel profile." : ""}`),
            parameters.length <= 2 ? `${head}${parameters.join(", ")});` : head,
            ...(parameters.length <= 2 ? [] : [...indent(parameters.map((parameter) => `${parameter},`)), ");"]),
          ];
        }),
      ),
    ),
    "}",
  ]);
  const holder: Lines = [
    "/// Every operation group the panel implements.",
    "final class PortableKernel {",
    ...indent([
      "const PortableKernel({",
      ...indent(groups.map(([group]) => `required this.${groupField(group)},`)),
      "});",
      BLANK,
      ...groups.map(([group]) => `final ${kernelName(group)} ${groupField(group)};`),
    ]),
    "}",
  ];
  return [...interfaces, holder];
}

function invoker(catalog: ResolvedOperations, skir: Skir): Lines {
  return [
    "/// Runs operation [id] with the call rule's arguments, or returns null when this",
    "/// build does not know it.",
    `PortableMaybe<${skir.dataValue}>? invokePortableOperation(`,
    ...indent([
      "PortableKernel kernel,",
      "String id,",
      "List<KernelArgument> arguments,",
      `List<${skir.typeUse}> typeArguments,`,
      "KernelContext context,",
    ]),
    ") => switch (id) {",
    ...indent(catalog.operations.flatMap((operation) => invokerCase(operation, catalog))),
    ...indent(["_ => null,"]),
    "};",
  ];
}

function invokerCase(operation: ResolvedOperation, catalog: ResolvedOperations): Lines {
  const argumentsOf = operation.parameters.map((parameter, index) => argument(parameter, index, operation, catalog));
  const typeArguments = operation.typeParameters.filter((parameter) => parameter.explicit).map((_, index) => `typeArguments[${index}]`);
  const capabilities = operation.uses.map((use) => `context.${use}`);
  const call = `kernel.${groupField(operation.group)}.${methodName(operation)}(${[...argumentsOf, ...typeArguments, ...capabilities].join(", ")})`;
  const body =
    operation.result.kind === "maybe"
      ? `${call}.map((it) => ${encode(operation.result.value, "it", catalog, operation)})`
      : `PortableMaybeValue(${encode(operation.result, call, catalog, operation)})`;
  return [`${quoted(operation.id)} => ${body},`];
}

function argument(parameter: ResolvedParameter, index: number, operation: ResolvedOperation, catalog: ResolvedOperations): string {
  if (parameter.variadic) {
    return `[for (final it in arguments.skip(${index})) ${decode(parameter.type, "it.value", catalog, operation)}]`;
  }
  const at = `arguments[${index}]`;
  switch (parameter.kind) {
    case "value":
    case "partial":
      return decode(parameter.type, `${at}.value`, catalog, operation);
    case "located":
      return `${at}.located((it) => ${decode(unwrapped(parameter.type), "it", catalog, operation)})`;
    case "each": {
      const output = (parameter.type as { output: Signature }).output;
      return `${at}.each((it) => ${decode(output, "it", catalog, operation)})`;
    }
    case "step":
      return `${at}.step`;
    case "comparator":
      return `${at}.comparator`;
    case "apply":
      return `${at}.apply`;
  }
}
